import XCTest
@testable import UmbelCore

final class ASSStyleSheetTests: XCTestCase {
  /// What FFmpeg generates for an SRT track: one default style, PlayResY 288.
  private let ffmpegDefaultHeader = """
    [Script Info]
    ; Script generated by FFmpeg/Lavc63.1.101
    ScriptType: v4.00+
    PlayResX: 384
    PlayResY: 288
    ScaledBorderAndShadow: yes

    [V4+ Styles]
    Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
    Style: Default,Arial,16,&Hffffff,&Hffffff,&H0,&H0,0,0,0,0,100,100,0,0,1,1,0,2,10,10,10,0

    [Events]
    Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
    """

  func testParsesTheDefaultStyleFFmpegGenerates() throws {
    let sheet = ASSStyleSheet(header: ffmpegDefaultHeader)
    XCTAssertEqual(sheet.playResX, 384)
    XCTAssertEqual(sheet.playResY, 288)
    let style = try XCTUnwrap(sheet.style(named: "Default"))
    XCTAssertEqual(style.fontName, "Arial")
    XCTAssertEqual(style.fontSize, 16)
    XCTAssertEqual(style.primaryColor, UmbelColor(red: 1, green: 1, blue: 1, alpha: 1))
    XCTAssertEqual(style.outlineColor, UmbelColor(red: 0, green: 0, blue: 0, alpha: 1))
    XCTAssertEqual(style.alignment, .bottomCenter)
    XCTAssertEqual(style.outlineWidth, 1)
    XCTAssertEqual(style.marginVertical, 10)
    XCTAssertFalse(style.isBold)
  }

  /// Authors reorder columns; the Format line says where each one is.
  func testFollowsTheFormatLineOrder() throws {
    let header = """
      [Script Info]
      PlayResY: 720

      [V4+ Styles]
      Format: Name, Alignment, Bold, Italic, Fontsize, PrimaryColour
      Style: Sign,8,-1,1,48,&H000000FF
      """
    let sheet = ASSStyleSheet(header: header)
    let style = try XCTUnwrap(sheet.style(named: "Sign"))
    XCTAssertEqual(style.alignment, .topCenter)
    XCTAssertTrue(style.isBold, "ASS writes true as -1")
    XCTAssertTrue(style.isItalic)
    XCTAssertEqual(style.fontSize, 48)
    XCTAssertEqual(style.primaryColor, UmbelColor(red: 1, green: 0, blue: 0, alpha: 1))
  }

  /// Colours are &HAABBGGRR, and alpha counts transparency, not opacity.
  func testColourIsBGRWithInvertedAlpha() {
    XCTAssertEqual(
      ASSStyleSheet.color("&H80FF0000"),
      UmbelColor(red: 0, green: 0, blue: 1, alpha: Double(0x7F) / 255))
    XCTAssertEqual(ASSStyleSheet.color("&H00ff00&"), UmbelColor(red: 0, green: 1, blue: 0, alpha: 1))
    // SSA files sometimes write colours as decimal.
    XCTAssertEqual(ASSStyleSheet.color("255"), UmbelColor(red: 1, green: 0, blue: 0, alpha: 1))
  }

  /// SSA v4 numbers alignment differently: 1–3 bottom, +4 top, +8 middle.
  func testLegacySSAAlignment() throws {
    let header = """
      [V4 Styles]
      Format: Name, Alignment
      Style: Top,6
      Style: Middle,9
      """
    let sheet = ASSStyleSheet(header: header)
    XCTAssertEqual(sheet.style(named: "Top")?.alignment, .topCenter)
    XCTAssertEqual(sheet.style(named: "Middle")?.alignment, .middleLeft)
  }

  func testMissingPlayResFallsBackLikeTheReferenceRenderer() {
    let sheet = ASSStyleSheet(header: "[Script Info]\nPlayResY: 480\n")
    XCTAssertEqual(sheet.playResY, 480)
    XCTAssertEqual(sheet.playResX, 640, "only Y given: X = Y * 4 / 3")
    let empty = ASSStyleSheet(header: "")
    XCTAssertEqual(empty.playResY, 288)
    XCTAssertEqual(empty.playResX, 384)
  }

  func testUnknownStyleFallsBackToDefault() {
    let sheet = ASSStyleSheet(header: ffmpegDefaultHeader)
    XCTAssertEqual(sheet.resolvedStyle(named: "Nope").fontName, "Arial")
    XCTAssertEqual(ASSStyleSheet(header: "").resolvedStyle(named: "Default").alignment, .bottomCenter)
  }
}
